28	- (instancetype)initWithSink:(void (^)(NSString *))sink
29	{
30		self = [super init];
31		if (self)
32		{
33			_accumulated = [NSMutableData data];
34			_undecoded = [NSMutableData data];
35			_sink = [sink copy];
36		}
37		return self;
38	}
