40	- (void)appendData:(NSData *)data
41	{
42		if (data.length == 0)
43		{
44			return;
45		}
46	
47		@synchronized (self)
48		{
49			[_accumulated appendData:data];
50	
51			// A pipe read can split a multi-byte character (brew prints ✔/✘/→), so
52			// hold bytes that don't yet decode until the rest arrives.
53			[_undecoded appendData:data];
54			NSString *chunk = [[NSString alloc] initWithData:_undecoded encoding:NSUTF8StringEncoding];
55			if (!chunk)
56			{
57				return;
58			}
59			[_undecoded setLength:0];
60	
61			// Forwarded inside the lock so chunks reach the sink in order; the sink
62			// is an async XPC proxy call, so this doesn't block on the peer.
63			if (_sink && chunk.length > 0)
64			{
65				_sink(chunk);
66			}
67		}
68	}
